input.sparql:
SELECT ?tsid ?point ?class WHERE {
  ?point a brick:Fan ; ?point brick:hasTag "SupplyFan_AHU01" .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdf:type ?class . }
}

SELECT ?point ?class WHERE {
  ?point a ?class .
  FILTER(STRCONTAINS(STR(?point), "SupplyFan") || STRCONTAINS(STR(?point), "AHU01") || STRCONTAINS(STR(?point), "fan"))
} LIMIT 200
